private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        return node;
    }
    try {
        node.left = left.right;
        if (left.right != null) {
            left.right.parent = node;
        }
        left.right = node;
        left.parent = node.parent;
        node.parent = left;
        return left;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

