private int parseEndOfLine(String headerPart,int end){
    if(headerPart==null) return -1;
    int length = headerPart.length();
    try{
        while(end+1 < length){
            if(headerPart.charAt(end)=='\r' && headerPart.charAt(end+1)=='\n'){
                return end;
            }
            end++;
        }
    }catch(IndexOutOfBoundsException e){
        // If end is out of bounds just return -1
        return -1;
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("end index is out of bounds");
    }
    for (int i = end; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    // Validate inputs
    if (headerPart == null || headerPart.isEmpty()) {
        return -1;
    }
    if (end < 0 || end >= headerPart.length()) {
        return -1;
    }
    // Find the CRLF sequence starting from the given index
    int idx = headerPart.indexOf("\r\n", end);
    return idx;
}

