}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    try {
        java.util.Deque<File> stack = new java.util.ArrayDeque<>();
        stack.push(file);
        while (!stack.isEmpty()) {
            File f = stack.pop();
            if (f.isDirectory()) {
                f.deleteOnExit();
                File[] children = f.listFiles();
                if (children == null) {
                    throw new IOException("Unable to list contents of directory: " + f);
                }
                for (File child : children) {
                    if (child != null) {
                        stack.push(child);
                    }
                }
            } else {
                f.deleteOnExit();
            }
        }
    } catch (SecurityException e) {
        throw new IOException("Unable to register delete on exit for: " + file, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    try {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) {
                for (File child : children) {
                    forceDeleteOnExit(child);
                }
            }
        }
        file.deleteOnExit();
    } catch (SecurityException se) {
        throw new IOException("Unable to schedule deletion on exit for: " + file, se);
    }
}

