    V left1 = target.addVertex("U1");
    V left2 = target.addVertex("U2");
    V right1 = target.addVertex("V1");
    V right2 = target.addVertex("V2");
    target.addEdge(left1, right1);
    target.addEdge(left1, right2);
    target.addEdge(left2, right1);
    target.addEdge(left2, right2);
    resultMap.put("left1", left1);
    resultMap.put("left2", left2);
    resultMap.put("right1", right1);
    resultMap.put("right2", right2);
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if(target == null || resultMap == null || resultMap.isEmpty()) return;
    try{
        // Add all vertices to the target graph
        for(V v : resultMap.values()){
            target.addVertex(v);
        }
        // Partition vertices into two sets arbitrarily: first half left, second half right
        List<V> vertexList = new ArrayList<>(resultMap.values());
        int split = vertexList.size() / 2;
        List<V> left = vertexList.subList(0, split);
        List<V> right = vertexList.subList(split, vertexList.size());
        // Connect every left vertex to every right vertex
        for(V u : left){
            for(V w : right){
                target.addEdge(u, w);
            }
        }
    }catch(Exception e){
        // If any operation fails, wrap and rethrow as runtime exception for visibility
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) return;
    // Add all vertices from the result map into the target graph
    for (V vertex : resultMap.values()){
        if (vertex != null){
            target.addVertex(vertex);
        }
    }
    // Build a list of vertices to easily partition them
    List<V> vertices = new ArrayList<>(resultMap.values());
    int size = vertices.size();
    if (size < 2) return; // nothing to connect
    int mid = size / 2; // split roughly in half
    for (int i = 0; i < mid; i++){
        V u = vertices.get(i);
        if (u == null) continue;
        for (int j = mid; j < size; j++){
            V v = vertices.get(j);
            if (v == null) continue;
            // Add edge to create a complete bipartite graph
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    int leftSize = 3;
    int rightSize = 3;
    java.util.ArrayList<String> leftKeys = new java.util.ArrayList<>();
    java.util.ArrayList<String> rightKeys = new java.util.ArrayList<>();
    for(int i = 1; i <= leftSize; i++){
        String key = "L" + i;
        leftKeys.add(key);
        resultMap.put(key, (V)(Object)key);
    }
    for(int i = 1; i <= rightSize; i++){
        String key = "R" + i;
        rightKeys.add(key);
        resultMap.put(key, (V)(Object)key);
    }
    for(String u : leftKeys){
        for(String v : rightKeys){
            target.addEdge((V)(Object)u, (V)(Object)v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
