        throw new IllegalArgumentException("Target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("resultMap cannot be null");
    }
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if (n < 2) {
        return; // nothing to connect in a bipartite graph
    }
    int mid = n / 2;
    List<V> left = vertices.subList(0, mid);
    List<V> right = vertices.subList(mid, n);
    for (V u : left) {
        for (V v : right) {
            try {
                target.addEdge(u, v);
            } catch (Exception e) {
                // swallow edge-creation errors to keep method robust
            }
        }
    }
}

