public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) throw new IllegalArgumentException("OutputStream must not be null");
    if (message == null) throw new IllegalArgumentException("Message must not be null");
    if (schema == null) throw new IllegalArgumentException("Schema must not be null");
    // Compute serialized size
    int size = schema.computeSize(message);
    if (size < 0) throw new IllegalArgumentException("Computed size is negative: " + size);
    // Write length prefix as varint
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Write the actual message
    if (buffer != null) {
        schema.writeTo(cos, message, buffer);
    } else {
        // Fallback: write without a buffer (may allocate internally)
        schema.writeTo(cos, message, LinkedBuffer.allocate());
    }
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    // Determine the size of the serialized message
    int size = schema.serializedSize(message);
    // Create a coded output stream that writes to the provided OutputStream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    // Write the length prefix as a varint32
    cos.writeInt32NoTag(size);
    // Write the actual message bytes
    schema.writeTo(message, cos);
    // Flush the output stream to ensure all bytes are written
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message is null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema is null");
    }
    // Serialize the message into a temporary byte array
    ByteArrayOutputStream temp = new ByteArrayOutputStream();
    try {
        // Attempt to use the provided buffer if the schema supports it.
        // If the schema does not provide a method to directly write to an OutputStream,
        // we fall back to using a generic writeTo implementation.
        boolean wrote = false;
        try {
            // Try using a WriteTo(OutputStream, T) method if available
            schema.writeTo(temp, message);
            wrote = true;
        } catch (AbstractMethodError | NoSuchMethodError e) {
            // Fallback: use the deprecated generic serialization logic
            // Compute size for length prefix
            int size = schema.getSerializedSize(message);
            temp.writeInt(size);
            // Write the serialized message
            CodedOutputStream cos = CodedOutputStream.newInstance(temp);
            schema.writeTo(cos, message);
            cos.flush();
            wrote = true;
        }
        if (!wrote) {
            throw new IOException("Unable to serialize message");
        }
    } catch (IOException e) {
        throw e;
    }
    byte[] data = temp.toByteArray();
    int size = data.length;
    // Write a 4‑byte big‑endian length prefix
    out.write((byte) (size >> 24));
    out.write((byte) (size >> 16));
    out.write((byte) (size >> 8));
    out.write((byte) (size));
    // Write the actual message bytes
    out.write(data);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream 'out' must not be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message must not be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema must not be null");
    }
    if (buffer == null) {
        buffer = LinkedBuffer.allocate();
    }

    // Determine encoded length and fill buffer
    int size = schema.getEncodedLength(message, buffer);
    if (size < 0) {
        throw new IllegalStateException("Encoded length cannot be negative");
    }

    // Write the size as a varint prefix
    int val = size;
    while ((val & ~0x7F) != 0) {
        out.write((val & 0x7F) | 0x80);
        val >>>= 7;
    }
    out.write(val);

    // Write the serialized bytes to the output stream
    buffer.writeTo(out);
    buffer.recycle();

    return size;
}

