private static Class<?> resolveTypeToClass(Type type, java.util.Map<java.lang.reflect.TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof java.lang.reflect.ParameterizedType) {
        java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) type;
        return (Class<?>) pt.getRawType();
    }
    if (type instanceof java.lang.reflect.GenericArrayType) {
        java.lang.reflect.Type comp = ((java.lang.reflect.GenericArrayType) type).getGenericComponentType();
        Class<?> compClass = resolveTypeToClass(comp, map);
        if (compClass == null) {
            return null;
        }
        return java.lang.reflect.Array.newInstance(compClass, 0).getClass();
    }
    if (type instanceof java.lang.reflect.TypeVariable<?>) {
        Type resolved = map.get(type);
        if (resolved == null) {
            return null;
        }
        // Resolve recursively in case the resolved type is another TypeVariable
        return resolveTypeToClass(resolved, map);
    }
    if (type instanceof java.lang.reflect.WildcardType) {
        java.lang.reflect.WildcardType wc = (java.lang.reflect.WildcardType) type;
        java.lang.reflect.Type[] upper = wc.getUpperBounds();
        if (upper.length > 0) {
            return resolveTypeToClass(upper[0], map);
        }
        return null;
    }
    return null;
}

