        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> type) {
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    Set<Class<?>> visited = new HashSet<>();
    ArrayDeque<Class<?>> stack = new ArrayDeque<>();
    stack.push(type);
    while (!stack.isEmpty()) {
        Class<?> current = stack.pop();
        if (current == null || !visited.add(current)) {
            continue;
        }
        Type superType = current.getGenericSuperclass();
        if (superType instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) superType;
            Class<?> raw = (Class<?>) pt.getRawType();
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                if (!map.containsKey(vars[i])) {
                    map.put(vars[i], args[i]);
                }
            }
            stack.push(raw);
        }
        for (Type iface : current.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pt = (ParameterizedType) iface;
                Class<?> raw = (Class<?>) pt.getRawType();
                TypeVariable<?>[] vars = raw.getTypeParameters();
                Type[] args = pt.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    if (!map.containsKey(vars[i])) {
                        map.put(vars[i], args[i]);
                    }
                }
                stack.push(raw);
            }
        }
    }
    return map;
}

private static Class<?> resolveType(Map<TypeVariable<?>, Type> map, Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof TypeVariable<?>) {
        Type resolved = map.get(type);
        if (resolved == null || resolved.equals(type)) {
            return null;
        }
        return resolveType(map, resolved);
    }
    return null;
}

