protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }
    if (start > end) {
        throw new IllegalArgumentException("start (" + start + ") must not be greater than end (" + end + ")");
    }
    if (start == end) {
        return new ArrayList<>(0);
    }

    List<TimeRange> ranges = new ArrayList<>();
    long step = FETCH_DATA_DURATION;
    for (long current = start; current < end; ) {
        long next;
        if (current > Long.MAX_VALUE - step) {
            next = end;
        } else {
            next = Math.min(end, current + step);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){ 
    List<TimeRange> ranges = new ArrayList<TimeRange>(); 
    if (start >= end) { 
        return ranges; 
    } 
    long current = start; 
    while (current < end) { 
        long rangeEnd = Math.min(current + FETCH_DATA_DURATION, end); 
        ranges.add(new TimeRange(current, rangeEnd)); 
        current = rangeEnd; 
    } 
    return ranges; 
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    final long chunk = FETCH_DATA_DURATION;
    if (chunk <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long from = start;
    while (from < end) {
        long to;
        if (from > Long.MAX_VALUE - chunk) {
            to = end;
        } else {
            to = Math.min(from + chunk, end);
        }
        ranges.add(new TimeRange(from, to));
        from = to;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    // Validate input range
    if (start >= end || start < 0 || end < 0) {
        // Return an empty list for invalid or empty ranges
        return new ArrayList<>();
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        // Calculate the size of the next chunk
        long remaining = end - current;
        long chunk = Math.min(FETCH_DATA_DURATION, remaining);
        // Guard against potential overflow (chunk <= remaining ensures this)
        long rangeEnd = current + chunk;
        // Create the time range and add to the list
        ranges.add(new TimeRange(current, rangeEnd));
        // Move to the next segment
        current = rangeEnd;
    }
    return ranges;
}

