private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    if (suffixLen > str.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, str.length() - suffixLen, suffix, 0, suffixLen);
    }
    return str.endsWith(suffix);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Both null => true, one null => false
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    // Suffix longer than string cannot match
    if (suffix.length() > str.length()) {
        return false;
    }
    int startIdx = str.length() - suffix.length();
    try {
        return str.regionMatches(ignoreCase, startIdx, suffix, 0, suffix.length());
    } catch (IndexOutOfBoundsException e) {
        // This should not happen due to the length check, but guard anyway
        return false;
    }
}

