    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        // regionMatches supports case-insensitive comparison
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

