public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Ignore leading '/' for absolute paths
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return segments;
    }
    String[] rawSegments = rawPath.split("/");
    for (String rawSegment : rawSegments) {
        if (rawSegment.isEmpty()) {
            // Skip empty segments resulting from consecutive slashes
            continue;
        }
        String segment;
        if (decode) {
            try {
                segment = URLDecoder.decode(rawSegment, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; wrap in unchecked exception if it occurs
                throw new RuntimeException(e);
            }
        } else {
            segment = rawSegment;
        }
        // Create a PathSegmentImpl instance; assume it has a constructor that accepts the decoded segment string
        segments.add(new PathSegmentImpl(segment));
    }
    return segments;
}

