private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int start = 0;
    int end = descriptor.length();
    // If it's a method descriptor, skip the return type
    if (descriptor.charAt(0) == '(') {
        int close = descriptor.indexOf(')');
        if (close < 0) { // malformed descriptor
            return;
        }
        start = 1;
        end = close;
    }
    int i = start;
    while (i < end) {
        char c = descriptor.charAt(i);
        switch (c) {
            case 'J': // long
            case 'D': // double
                // long and double use two slots
                pop(); // first slot
                pop(); // second slot
                i++;
                break;
            case '[': { // array type – pop a single reference
                // skip all '[' characters
                while (i < end && descriptor.charAt(i) == '[') {
                    i++;
                }
                // consume the element type but ignore its specific form
                if (i < end) {
                    char elem = descriptor.charAt(i);
                    if (elem == 'L') { // object type inside array
                        i++; // skip 'L'
                        while (i < end && descriptor.charAt(i) != ';') {
                            i++;
                        }
                        i++; // skip ';'
                    } else { // primitive inside array
                        i++; // skip the primitive type
                    }
                }
                pop(); // array is a reference, only one slot
                break;
            }
            case 'L': { // object type
                i++; // skip 'L'
                while (i < end && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
                pop(); // object reference occupies one slot
                break;
            }
            default: // primitive type (B, C, I, S, Z, etc.)
                pop(); // occupies one slot
