private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int p = 0;
    int len = descriptor.length();
    // Helper to reduce the stack pointer with underflow check
    Runnable popOne = () -> {
        if (pos <= 0) throw new IndexOutOfBoundsException("Stack underflow");
        pos--;
    };
    if (descriptor.charAt(0) == '('){
        p = 1;
        while (p < len){
            char c = descriptor.charAt(p);
            if (c == ')'){
                break;
            }
            // Consume the next type description
            if (c == '['){
                // array type, consume all '[' and the component type
                while (p < len && descriptor.charAt(p) == '[') p++;
                if (p >= len) throw new IllegalArgumentException("Invalid descriptor");
                c = descriptor.charAt(p);
                if (c == 'L'){
                    int sem = descriptor.indexOf(';', p + 1);
                    if (sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                    p = sem + 1;
                } else {
                    p++;
                }
            } else if (c == 'L'){
                int sem = descriptor.indexOf(';', p + 1);
                if (sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                p = sem + 1;
            } else {
                // Primitive type (single char)
                p++;
            }
            // Pop one stack slot for the type
            if (pos <= 0) throw new IndexOutOfBoundsException("Stack underflow");
            pos--;
        }
    } else {
        // Descriptor represents a single type
        char c = descriptor.charAt(p);
        if (c == '['){
            while (p < len && descriptor.charAt(p) == '[') p++;
            if (p >= len) throw new IllegalArgumentException("Invalid descriptor");
            c = descriptor.charAt(p);
            if (c == 'L'){
                int sem = descriptor.indexOf(';', p + 1);
                if (sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                p = sem + 1;
            } else {
                p++;
            }
        } else if (c == 'L'){
            int sem = descriptor.indexOf(';', p + 1);
            if (sem == -1) throw new IllegalArgumentException("Invalid descriptor");
            p = sem + 1;
        } else {
            p++;
        }
        if (pos <= 0) throw new IndexOutOfBoundsException("Stack underflow");
        pos--;
    }
}

