private void enlarge(final int size) {
    // size must be non-negative; otherwise the request is nonsensical
    if (size < 0) {
        throw new IllegalArgumentException("Size to enlarge by must be non-negative");
    }

    // If no extra space is needed, simply return
    if (size == 0) {
        return;
    }

    // Guard against null data array (should not normally happen in a well‑formed ByteVector)
    if (data == null) {
        data = new byte[Math.max(1, size)];
        length = 0;
        return;
    }

    // Determine the required capacity
    int currentCapacity = data.length;
    long minNeeded = (long) length + (long) size;
    if (minNeeded < 0) { // overflow: treat as maximum integer size
        minNeeded = Integer.MAX_VALUE;
    }

    // Double the capacity as a growth strategy, but ensure we reach the minimum needed
    long doubled = (long) currentCapacity * 2;
    long newCapacity = Math.max(doubled, minNeeded);
    if (newCapacity > Integer.MAX_VALUE) {
        newCapacity = Integer.MAX_VALUE;
    }

    // If the current capacity already satisfies the requirement, no need to resize
    if (newCapacity <= currentCapacity) {
        return;
    }

    // Create the new array and copy existing data
    byte[] newData = new byte[(int) newCapacity];
    System.arraycopy(data, 0, newData, 0, length);
    data = newData;
}

private void enlarge(final int size){
        if (size <= 0){
            return;
        }
        int currentCapacity = (data == null) ? 0 : data.length;
        if (currentCapacity >= length + size){
            return;
        }
        int newCapacity;
        if (currentCapacity == 0){
            newCapacity = Math.max(1, length + size);
        }else{
            newCapacity = 2 * currentCapacity;
            if (newCapacity < length + size){
                newCapacity = length + size;
            }
        }
        byte[] newData = new byte[newCapacity];
        if (data != null && length > 0){
            System.arraycopy(data, 0, newData, 0, length);
        }
        data = newData;
}

private void enlarge(final int size){
    int cap = 2 * data.length;
    int newSize = length + size;
    byte[] newData = new byte[cap > newSize ? cap : newSize];
    System.arraycopy(data, 0, newData, 0, length);
    data = newData;
}

