private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null || stackMapTableEntries == null) {
        return;
    }
    for (int i = start; i < end; ++i) {
        Type current = currentFrame[i];
        if (current == null) {
            // Undefined/invalid type, skip or throw
            throw new IllegalArgumentException("Null type at frame index " + i);
        }
        int sort = current.getSort();
        switch (sort) {
            case Type.VOID:        // TOP
                stackMapTableEntries.putByte(0);
                break;
            case Type.BOOLEAN:
            case Type.CHAR:
            case Type.BYTE:
            case Type.SHORT:
            case Type.INT:         // INTEGER
                stackMapTableEntries.putByte(1);
                break;
            case Type.FLOAT:       // FLOAT
                stackMapTableEntries.putByte(2);
                break;
            case Type.LONG:        // LONG
                stackMapTableEntries.putByte(3);
                break;
            case Type.DOUBLE:      // DOUBLE
                stackMapTableEntries.putByte(4);
                break;
            case Type.OBJECT:      // OBJECT
                stackMapTableEntries.putByte(7);
                stackMapTableEntries.putShort(constantPool.putClassInfo(current.getClassName()));
                break;
            case Type.ARRAY:       // ARRAY treated as OBJECT
                stackMapTableEntries.putByte(7);
                stackMapTableEntries.putShort(constantPool.putClassInfo(current.getDescriptor()));
                break;
            case Type.UNINITIALIZED: // UNINITIALIZED
                stackMapTableEntries.putByte(8);
                stackMapTableEntries.putShort((short) current.getOffset());
                break;
            default:
                throw new IllegalArgumentException("Unsupported type sort: " + sort);
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        VerificationType vt = currentFrame.get(i);
        int tag = vt.getTag();
        stackMapTableEntries.putByte((byte) tag);
        if (tag == 7) { // Object
            int classInfoIndex = vt.getClassInfoIndex();
            stackMapTableEntries.putShort(classInfoIndex);
        } else if (tag == 8) { // Uninitialized
            int offset = vt.getObjectData();
            stackMapTableEntries.putShort(offset);
        }
    }
}

