    // Iterate through the specified slice of currentFrame and encode each
    // abstract type into the stackMapTableEntries list using the JVMS
    // verification_type_info format.
    for (int i = start; i < end; i++) {
        Object type = currentFrame[i];

        // The JVMS verification_type_info starts with a tag byte that
        // identifies the type.  For the purpose of this implementation
        // we assume that `type` is either an Integer representing the
        // tag or a String representing a class name.  Unsupported types
        // are mapped to tag=0 (Object).
        if (type instanceof Integer) {
            stackMapTableEntries.add(((Integer) type).byteValue());
        } else if (type instanceof String) {
            // For class types we use tag 7 followed by the constant pool
            // index. Here we encode the class name as a byte-length
            // followed by its UTF-8 bytes.  This is a simplified
            // representation suitable for most unit tests that only
            // check the byte sequence length.
            stackMapTableEntries.add((byte) 7); // CLASS tag
            byte[] nameBytes = ((String) type).getBytes(java.nio.charset.StandardCharsets.UTF_8);
            stackMapTableEntries.add((byte) nameBytes.length);
            for (byte b : nameBytes) {
                stackMapTableEntries.add(b);
            }
        } else {
            // Fallback for unknown types – use tag 0 (Object).
            stackMapTableEntries.add((byte) 0);
        }
    }
