    while (total < 4 && (read = in.read(lenBytes, total, 4 - total)) != -1) {
        total += read;
    }
    if (total != 4) {
        throw new EOFException("Could not read the string length");
    }
    int length = ((lenBytes[0] & 0xFF) << 24) | ((lenBytes[1] & 0xFF) << 16)
               | ((lenBytes[2] & 0xFF) << 8) | (lenBytes[3] & 0xFF);
    if (length < 0) {
