    }
    Map<String,Object> map = new HashMap<>();
    for(Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement value = entry.getValue();
        if(value == null || value.isJsonNull()){
            map.put(key, null);
        }else if(value.isJsonPrimitive()){
            JsonPrimitive prim = value.getAsJsonPrimitive();
            if(prim.isBoolean()){
                map.put(key, prim.getAsBoolean());
            }else if(prim.isNumber()){
                map.put(key, prim.getAsNumber());
            }else{
                map.put(key, prim.getAsString());
            }
        }else if(value.isJsonObject()){
            map.put(key, buildContent(value.getAsJsonObject()));
        }else if(value.isJsonArray()){
            List<Object> list = new ArrayList<>();
            for(JsonElement elem : value.getAsJsonArray()){
                if(elem.isJsonPrimitive()){
                    JsonPrimitive p = elem.getAsJsonPrimitive();
                    if(p.isBoolean()){
                        list.add(p.getAsBoolean());
                    }else if(p.isNumber()){
                        list.add(p.getAsNumber());
                    }else{
                        list.add(p.getAsString());
                    }
                }else if(elem.isJsonObject()){
                    list.add(buildContent(elem.getAsJsonObject()));
                }else if(elem.isJsonArray()){
                    // nested array - convert to list recursively
                    list.add(buildArrayToList(elem.getAsJsonArray()));
                }else{
                    list.add(null);
                }
            }
            map.put(key, list);
        }else{
            map.put(key, null);
        }
    }
