}

private List<Object> buildArrayToList(JsonArray array){
    List<Object> list = new ArrayList<>();
    for(JsonElement elem : array){
        if(elem.isJsonPrimitive()){
            JsonPrimitive p = elem.getAsJsonPrimitive();
            if(p.isBoolean()){
                list.add(p.getAsBoolean());
            }else if(p.isNumber()){
                list.add(p.getAsNumber());
            }else{
                list.add(p.getAsString());
            }
        }else if(elem.isJsonObject()){
            list.add(buildContent(elem.getAsJsonObject()));
        }else if(elem.isJsonArray()){
            list.add(buildArrayToList(elem.getAsJsonArray()));
        }else{
            list.add(null);
        }
    }
    return list;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if (jsonObject == null) {
        return result;
    }
    try {
        for (Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
            String key = entry.getKey();
            JsonElement elem = entry.getValue();
            Object value = null;
            if (elem.isJsonNull()){
                value = null;
            } else if (elem.isJsonPrimitive()){
                JsonPrimitive prim = elem.getAsJsonPrimitive();
                if (prim.isBoolean()){
                    value = prim.getAsBoolean();
                } else if (prim.isNumber()){
                    Number num = prim.getAsNumber();
                    if (num.doubleValue() % 1 == 0){
                        value = num.longValue();
                    } else {
                        value = num.doubleValue();
                    }
                } else if (prim.isString()){
                    value = prim.getAsString();
                }
            } else {
                // keep JsonElement for objects/arrays
                value = elem;
            }
            // if key is 'ats', set it specially
            if ("ats".equals(key)){
                result.put("ats", value);
            } else {
                result.put(key, value);
            }
        }
    } catch (Exception e){
        // log or ignore to avoid breaking the caller
    }
    return result;
}

