private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new NullPointerException("newArrayComponentType must not be null when array is null");
        }
        return Array.newInstance(newArrayComponentType, 1);
    }
    if (!array.getClass().isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }
    Class<?> componentType = array.getClass().getComponentType();
    int oldLen = Array.getLength(array);
    Object newArray = Array.newInstance(componentType, oldLen + 1);
    System.arraycopy(array, 0, newArray, 0, oldLen);
    return newArray;
}

