private Set<V> intersection(Set<V> set1,Set<V> set2){
    if (set1 == null || set2 == null){
        return Collections.emptySet();
    }
    Set<V> result = new HashSet<>();
    if (set1.size() <= set2.size()){
        for (V e : set1){
            if (set2.contains(e)){
                result.add(e);
            }
        }
    } else {
        for (V e : set2){
            if (set1.contains(e)){
                result.add(e);
            }
        }
    }
    return result;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<V>();
    }
    // Determine the smaller set to iterate over for better performance
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger  = set1.size() <= set2.size() ? set2 : set1;
    Set<V> result = new HashSet<V>(Math.min(smaller.size(), larger.size()));
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

