            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) { // 'isActive' determines if the node is still in use
                    it.remove();        // remove inactive child
                    removedCount++;
                } else {
                    stack.push(child);   // keep exploring active nodes
                }
            }
        }
    } catch (Exception e) {
