protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume the class has a field 'root' of type Category representing the tree's root
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, drop the entire tree
        if (!root.isActive()) {
            root = null;
            return 0;
        }
        // Local helper class to keep track of a node and its parent
        class NodeInfo {
            Category parent;
            Category node;
            NodeInfo(Category p, Category n) { this.parent = p; this.node = n; }
        }
        // Use a stack to perform depth‑first traversal without recursion
        Deque<NodeInfo> stack = new ArrayDeque<>();
        for (Category child : new ArrayList<>(root.getChildren())) {
            stack.push(new NodeInfo(root, child));
        }
        while (!stack.isEmpty()) {
            NodeInfo info = stack.pop();
            Category parent = info.parent;
            Category current = info.node;
            // Push children onto the stack for later processing
            for (Category child : new ArrayList<>(current.getChildren())) {
                stack.push(new NodeInfo(current, child));
            }
            // Remove the node if it is inactive
            if (!current.isActive()) {
                parent.getChildren().remove(current);
                removedCount++;
            }
        }
    } catch (Exception e) {
        // Log or handle the exception as appropriate; here we print the stack trace
        e.printStackTrace();
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        if (rootCategories == null) {
            return 0;
        }
        // Use a stack for DFS traversal
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>(rootCategories);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            if (current == null) {
                continue;
            }
            if (!current.isActive()) {
                // Remove from parent or root list
                Category parent = current.getParent();
                if (parent != null) {
                    parent.getChildren().remove(current);
                } else {
                    rootCategories.remove(current);
                }
                // Count all nodes in this subtree (including the removed node)
                removedCount += countSubtreeNodes(current);
            } else {
                // Keep traversing active children
                for (Category child : current.getChildren()) {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected errors, quietly exit keeping partial results
    }
    return removedCount;
}

private int countSubtreeNodes(Category node) {
