}

protected int removeUnusedNodes(){
    // Handle null root
    if (root == null) {
        return 0;
    }
    // If root itself is inactive, remove entire tree
    if (!root.isActive()) {
        int totalRemoved = 0;
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category node = stack.pop();
            totalRemoved++;
            java.util.List<Category> children = node.getChildren();
            if (children != null) {
                stack.addAll(children);
            }
        }
        root = null; // clear tree reference
        return totalRemoved;
    }

    // Count removed nodes
    int removedCount = 0;
    // Stack for DFS traversal, each element is a parent node
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);

    while (!stack.isEmpty()) {
        Category parent = stack.pop();
        java.util.List<Category> children = parent.getChildren();
        if (children == null) {
            continue;
        }
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            // If child is inactive, remove entire subtree
            if (!child.isActive()) {
                // Count subtree nodes
                int subtreeSize = 0;
                java.util.Deque<Category> subStack = new java.util.ArrayDeque<>();
                subStack.push(child);
                while (!subStack.isEmpty()) {
                    Category n = subStack.pop();
                    subtreeSize++;
                    java.util.List<Category> g = n.getChildren();
                    if (g != null) {
                        subStack.addAll(g);
                    }
                }
                removedCount += subtreeSize;
                // Remove child from parent
                it.remove();
            } else {
                // Active child: traverse its descendants
                stack.push(child);
            }
        }
    }
    return removedCount;
}

protected int removeUnusedNodes(){
    int removed = 0;
    if (root == null) return 0;
    java.util.Deque<Category> stack = new java.util.ArrayDeque<Category>();
    stack.push(root);
    while (!stack.isEmpty()){
        Category curr = stack.pop();
        java.util.List<Category> children = curr.getChildren();
        if (children != null){
            for (int i = children.size() - 1; i >= 0; i--){
                Category child = children.get(i);
                if (!child.isActive()){
                    children.remove(i);
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    }
    return removed;
}

