public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("Overflow");
        }
        result *= i;
    }
    return result;
}

public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    // Create a circulator positioned at the start node.  The exact constructor signature
    // depends on the surrounding library, but in most cases an OuterFaceCirculator can
    // be instantiated with a node and a direction.  If that signature differs the code
    // will need to be adjusted accordingly.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the very first node satisfies the predicate or is the stop node we can
    // return immediately.
    if (predicate.test(circ.getNode())) {
        return circ;
    }
    if (circ.getNode().equals(stop)) {
        return circ;
    }

    // Use a set to guard against infinite loops in degenerate graphs.
    Set<Node> visited = new HashSet<>();
    visited.add(circ.getNode());

    while (true) {
        // Advance to the next node along the outer face boundary.
        circ.next(dir);

        Node current = circ.getNode();

        // If we return to a previously visited node we assume we have looped forever
        // without finding the stop node.
        if (!visited.add(current)) {
            // We cannot find a suitable node; fall back to the stop node.
            return new OuterFaceCirculator(stop, dir);
        }

        if (current.equals(stop)) {
            // We reached the stop node; no predicate match before the stop.
            return circ;
        }

        if (predicate.test(current)) {
            // Found a node that satisfies the predicate.
            return circ;
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        // If either node is null, return a circulator positioned at the stop node.
        return new OuterFaceCirculator(stop, dir);
    }
    // If the starting node already satisfies the predicate, return it immediately.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }
    // Otherwise return a circulator positioned at the stop node.
    return new OuterFaceCirculator(stop, dir);
}

