private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start must not be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the start node is the stop node, return immediately
    if (stop != null && circ.node().equals(stop)) {
        return circ;
    }
    // Iterate along the outer face until we hit the stop node or the predicate matches
    while (stop == null || !circ.node().equals(stop)) {
        if (predicate.test(circ.node())) {
            break;
        }
        OuterFaceCirculator next = circ.next();
        // Defensive guard against null or infinite loop
        if (next == null || next == circ) {
            break;
        }
        circ = next;
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null || start == null || stop == null){
        throw new IllegalArgumentException("predicate, start and stop must not be null");
    }
    // If start and stop are the same, return a circulator positioned at start/stop
    if (start.equals(stop)){
        return new OuterFaceCirculator(start, dir);
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.getNode(); // assume OuterFaceCirculator exposes the current node

    while (!current.equals(stop)){
        if (predicate.test(current)){
            return circ;
        }
        // Advance the circulator in the requested direction
        circ = dir > 0 ? circ.next() : circ.previous();
        current = circ.getNode();
    }

    // If we reached the stop node and it satisfies the predicate, return it; otherwise return a circulator positioned at stop
    if (predicate.test(stop)){
        return new OuterFaceCirculator(stop, dir);
    }
    return new OuterFaceCirculator(stop, dir);
}

