public static byte convertHexDigit(byte b){
    int c = b & 0xFF;
    if (c >= '0' && c <= '9') return (byte)(c - '0');
    if (c >= 'a' && c <= 'f') return (byte)(c - 'a' + 10);
    if (c >= 'A' && c <= 'F') return (byte)(c - 'A' + 10);
    throw new IllegalArgumentException("Invalid hex digit: " + (char)c);
}

public static byte convertHexDigit(byte b){
    if (b >= 48 && b <= 57) { // '0' to '9'
        return (byte)(b - 48);
    } else if (b >= 97 && b <= 102) { // 'a' to 'f'
        return (byte)(10 + (b - 97));
    } else if (b >= 65 && b <= 70) { // 'A' to 'F'
        return (byte)(10 + (b - 65));
    } else {
        throw new IllegalArgumentException("Invalid hex digit: " + (char)b);
    }
}

public static byte convertHexDigit(byte b) {
    // ASCII digits
    if (b >= '0' && b <= '9') {
        return (byte) (b - '0');
    }
    // ASCII lowercase a-f
    if (b >= 'a' && b <= 'f') {
        return (byte) (b - 'a' + 10);
    }
    // ASCII uppercase A-F
    if (b >= 'A' && b <= 'F') {
        return (byte) (b - 'A' + 10);
    }
    // Throw an exception for invalid hex characters
    throw new IllegalArgumentException("Invalid hex digit: " + (char) b);
