@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    // WebSocket transports are already kept alive; no need to suspend
    if (r.getTransport() == AtmosphereResource.TRANSPORT.WebSocket) {
        return Action.CONTINUE;
    }
    try {
        if (!r.isSuspended()) {
            r.suspend();
        }
    } catch (Throwable ignored) {
        // If suspension fails (e.g., already suspended or not supported), ignore and continue
    }
    return Action.CONTINUE;
}

