protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()){
        return null;
    }
    // Map vertex -> degree in the edge set
    Map<V,Integer> degree = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        degree.put(src, degree.getOrDefault(src, 0) + 1);
        degree.put(tgt, degree.getOrDefault(tgt, 0) + 1);
    }
    // Find a start vertex (degree 1 if possible)
    V start = null;
    for (Map.Entry<V,Integer> entry : degree.entrySet()){
        if (entry.getValue() == 1){
            start = entry.getKey();
            break;
        }
    }
    if (start == null){
        // Fall back to any vertex from the first edge
        E firstEdge = tour.iterator().next();
        start = graph.getEdgeSource(firstEdge);
    }

    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    V current = start;
    vertexList.add(current);

    while (!remaining.isEmpty()){
        boolean found = false;
        E nextEdge = null;
        V nextVertex = null;
        for (E e : remaining){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)){
                nextEdge = e;
                nextVertex = tgt;
                break;
            } else if (tgt.equals(current)){
                nextEdge = e;
                nextVertex = src;
                break;
            }
        }
        if (nextEdge == null){
            // No adjacent edge found; cannot form a continuous path
            return null;
        }
        edgeList.add(nextEdge);
        vertexList.add(nextVertex);
        current = nextVertex;
        remaining.remove(nextEdge);
        found = true;
    }

    try{
        return new GraphPathImpl<>(graph, vertexList, edgeList);
    }catch (Exception e){
        // If GraphPathImpl is not available, return null
        return null;
    }
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    try {
        if (tour == null || graph == null) {
            return null;
        }
        if (tour.isEmpty()) {
            return new DefaultGraphPath<V, E>(graph, Collections.emptyList(), Collections.emptyList());
        }
        // Maps to keep track of single outgoing/incoming edges per vertex
        Map<V, E> outgoing = new HashMap<>();
        Map<V, E> incoming = new HashMap<>();
        for (E e : tour) {
            if (e == null) {
                return null; // invalid edge
            }
            V u = graph.getEdgeSource(e);
            V v = graph.getEdgeTarget(e);
            // Ensure each vertex has at most one outgoing and one incoming edge
            if (outgoing.containsKey(u) || incoming.containsKey(v)) {
                return null; // not a simple path
            }
            outgoing.put(u, e);
            incoming.put(v, e);
        }
        // Find a start vertex: a vertex that is source but not target
        V start = null;
        for (V u : outgoing.keySet()) {
            if (!incoming.containsKey(u)) {
                start = u;
                break;
            }
        }
        // If no such vertex, it's a cycle; pick any source as start
        if (start == null) {
            start = outgoing.keySet().iterator().next();
        }
        List<V> vertexList = new ArrayList<>();
        List<E> edgeList = new ArrayList<>();
        V current = start;
        vertexList.add(current);
        // Walk along the path
        while (outgoing.containsKey(current)) {
            E e = outgoing.get(current);
            edgeList.add(e);
            V next = graph.getEdgeTarget(e);
            vertexList.add(next);
            current = next;
        }
        // Validate that all edges were used
        if (edgeList.size() != tour.size()) {
            return null; // missing edges or disconnected segments
        }
        return new DefaultGraphPath<V, E>(graph, vertexList, edgeList);
    } catch (Exception ex) {
        return null;
    }
}

