int addConstantNameAndType(final String name,final String descriptor){
    if(name == null || descriptor == null){
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // Create a simple deterministic index based on the lengths of the strings.
    // This keeps the same result for identical name/descriptor pairs.
    int nameLen = name.length();
    int descLen = descriptor.length();
    // Use bit shifting to combine lengths into a single int value.
    int hash = (nameLen << 16) ^ descLen;
    return hash;
}

