int addConstantNameAndType(final String name,final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // look for an existing CONSTANT_NameAndType entry
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == CONSTANT_NameAndType) {
            int nameIdx = readValue(i);          // value at position i contains the name index
            int descIdx = readValue(i + 1);      // descriptor index stored after the name
            if (decodeString(nameIdx).equals(name) && decodeString(descIdx).equals(descriptor)) {
                return i; // existing constant found
            }
        }
    }
    // add the name and descriptor to the pool, then create the NameAndType entry
    int nameIdx = addConstantUtf8(name);
    int descIdx = addConstantUtf8(descriptor);
    int newIndex = maxPoolSize++;
    // store the new constant's type and its name/descriptor indices
    types[newIndex] = CONSTANT_NameAndType;
    // assuming the constant pool stores the two sub-entries sequentially
    nameIndices[newIndex] = nameIdx;
    descriptorIndices[newIndex] = descIdx;
    return newIndex;
}

int addConstantNameAndType(final String name,final String descriptor){
    int existing = findNameAndType(name, descriptor);
    if (existing != NOT_FOUND) return existing;
    int nameIdx = findUtf8(name);
    if (nameIdx == NOT_FOUND) nameIdx = addUtf8(name);
    int descIdx = findUtf8(descriptor);
    if (descIdx == NOT_FOUND) descIdx = addUtf8(descriptor);
    return addPoolEntry(NAME_TYPE, nameIdx, descIdx);
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // First unescape any escaped backslashes, then unescape escaped dots.
    // This handles cases like "\\\\." -> "."
    String result = input.replace("\\\\", "\\");
    result = result.replace("\\.", ".");
    return result;
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            if (next == 'x' && i + 3 < input.length()) {
                String hex = input.substring(i + 2, i + 4);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    // If not a valid hex sequence, treat literally
                    sb.append('\\').append(next).append(hex);
                }
                i += 3; // Skip '\', 'x', and two hex digits
                continue;
            } else {
                // Generic escape: skip the backslash and use the following character
                sb.append(next);
                i++; // skip the escaped character
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            // Skip the backslash and append the escaped character
            i++;
            sb.append(input.charAt(i));
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(input.length());
    int len = input.length();
    int i = 0;
    while (i < len) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            // Skip the escape character and append the next character as literal
            result.append(input.charAt(i + 1));
            i += 2;
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Remove escape sequences for dots (i.e., replace "\." with ".")
    // This unescapes a string DOT identifier by simply stripping the escape for the dot.
    return input.replace("\\\\.", ".");
}

