private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate inputs
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    int bucketCount = bucketsByLabel.size();
    if (bucketCount == 0 || minLabel < 0 || minLabel >= bucketCount) {
        return;
    }

    // Source bucket containing vertices with label minLabel
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }

    // Destination bucket for label 0
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        // In case bucket 0 hasn't been initialized, create a new set
        dest = new HashSet<>();
        bucketsByLabel.set(0, dest);
    }

    // Move each vertex from source to dest, updating labels
    for (Integer vertex : source) {
        if (vertex == null || vertex < 0 || vertex >= labels.size()) {
            continue; // skip invalid vertex indices
        }
        // Update the label of the vertex to 0
        labels.set(vertex, 0);
        // Add vertex to bucket 0
        dest.add(vertex);
    }

    // Clear the source bucket
    source.clear();
}

