public static final <V>void reverse(V[] arr,int from,int to){
    if(arr==null||arr.length==0) return;
    int n=arr.length;
    if(from<0) from=0;
    if(to>=n) to=n-1;
    if(from>=to) return;
    while(from<to){
        V tmp=arr[from];
        arr[from]=arr[to];
        arr[to]=tmp;
        from++;
        to--;
    }
}

public static final <V> void reverse(V[] arr,int from,int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array is null");
    }
    int n = arr.length;
    if (from < 0 || to >= n || from > to) {
        throw new IndexOutOfBoundsException("Invalid range");
    }
    for (int i = 0, j = to; i < j; i++, j--) {
        V temp = arr[from + i];
        arr[from + i] = arr[j];
        arr[j] = temp;
    }
}

void function (Object[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    int n = arr.length;
    if (from < 0 || to < 0 || from >= n || to >= n) {
        throw new IndexOutOfBoundsException("Indices are out of bounds");
    }
    if (from > to) {
        return;
    }
    int i = from, j = to;
    while (i < j) {
        Object temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + " to=" + to + " for array length=" + arr.length);
    }
    int l = from;
    int r = to;
    while (l < r) {
        V temp = arr[l];
        arr[l] = arr[r];
        arr[r] = temp;
        l++;
        r--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    try {
        while (!list.isEmpty()) {
            // Assuming the list exposes a method to return its first node
            ListNode<E> node = list.getFirst();
            if (node == null) {
                // Defensive check in case getFirst() returned null
                break;
            }
            // Remove the node from the source list
            list.removeListNode(node);
            // Add the node to this list
            this.addListNode(node);
        }
    } catch (RuntimeException e) {
        // Wrap any unexpected runtime exception to give a clear message
        throw new RuntimeException("Failed to atomically move all list nodes", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
