private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list == this || list.isEmpty()) {
        return;
    }
    try {
        // Iterate over the source list removing each node and adding it to this list
        ListNodeImpl<E> node = list.getFirst();
        while (node != null) {
            // Keep a reference to the next node before altering the structure
            ListNodeImpl<E> next = node.getNext();
            list.removeListNode(node);
            addListNode(node);
            node = next;
        }
    } catch (Exception e) {
        // Log the exception if a logger is available; otherwise ignore to preserve atomicity
        // Example: Logger.getLogger(getClass().getName()).log(Level.WARNING, "Failed to move list nodes", e);
        throw new RuntimeException("Failed to move list nodes atomically", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Validate arguments
    if (list == null || list.isEmpty()) {
        return;
    }

    // Keep references to the nodes that will be moved
    ListNode<E> firstToMove = list.head;
    ListNode<E> lastToMove = list.tail;

    // Append the whole sequence to this list
    if (this.isEmpty()) {
        // If this list is empty, just point to the moved nodes
        this.head = firstToMove;
        this.tail = lastToMove;
    } else {
        // Connect the tail of this list to the new head
        this.tail.next = firstToMove;
        firstToMove.prev = this.tail;

        // Update the tail reference
        this.tail = lastToMove;
    }

    // Update sizes
    if (this.size >= 0 && list.size >= 0) { // guard against negative corruption
        this.size += list.size;
    } else {
        // Fallback to recompute if sizes were manipulated elsewhere
        this.size = 0;
        ListNode<E> node = this.head;
        while (node != null) {
            this.size++;
            node = node.next;
        }
    }

    // Reset the source list to an empty state
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list == this) return;
    try{
        // Iterate over nodes in the source list and transplant them into this list
        while (!list.isEmpty()){
            // Grab the first node of the source list
            ListNode<E> node = list.getHead();
            // Remove it from the source list then add it to this list
            list.removeListNode(node);
            this.addListNode(node);
        }
    }catch(Exception e){
        // If anything goes wrong, swallow the exception to keep the move atomic
        // and let the caller decide what to do
    }
}

