public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    Object sourceObj = map.getTargetObject();
    if (sourceObj == null) {
        return;
    }
    try {
        java.beans.PropertyDescriptor[] srcDescs =
            java.beans.Introspector.getBeanInfo(sourceObj.getClass()).getPropertyDescriptors();
        java.util.Set<String> writableProps = new java.util.HashSet<>();
        for (java.beans.PropertyDescriptor pd : srcDescs) {
            if (pd.getReadMethod() != null && pd.getWriteMethod() != null) {
                writableProps.add(pd.getName());
            }
        }
        for (String prop : writableProps) {
            try {
                Object value = map.get(prop);
                this.put(prop, value);
            } catch (Exception e) {
                // ignore properties that cannot be read or written
            }
        }
    } catch (Exception e) {
        // ignore reflection failures
    }
}

