    Object[] props = map.propertyNames();
    if (props == null) {
        return;
    }
    for (Object obj : props) {
        if (!(obj instanceof String)) {
            continue;
        }
        String prop = (String) obj;
        Object value;
        try {
            value = map.get(prop);
        } catch (Exception e) {
            // source property is write‑only; skip
            continue;
        }
        try {
            this.put(prop, value);
        } catch (Exception e) {
            // target property is read‑only or otherwise non‑writable; skip
        }
    }
}

public void putAllWriteable(BeanMap map){
