    try {
        for (Object keyObj : map.keySet()) {
            if (!(keyObj instanceof String)) {
                continue;
            }
            String key = (String) keyObj;
            java.beans.PropertyDescriptor pd = map.getPropertyDescriptor(key);
            if (pd != null && pd.getWriteMethod() != null) {
                this.put(key, map.get(key));
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to copy writable properties", e);
    }
}

