public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        return;
    }
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    int len = buf.length();
    if (start >= len) {
        return;
    }
    // Find the end of the word starting at nameStart
    int end = start;
    while (end < len && !Character.isWhitespace(buf.charAt(end))) {
        end++;
    }
    if (end <= start) {
        return;
    }
    char firstChar = buf.charAt(start);
    buf.append(firstChar).append('.');
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    // Assume the full name is obtainable via getName()
    String fullName = getName();
    if (fullName == null || fullName.isEmpty()) {
        return;
    }
    int len = fullName.length();
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start >= len) {
        return;
    }
    // Move to the first non‑whitespace character
    while (start < len && Character.isWhitespace(fullName.charAt(start))) {
        start++;
    }
    if (start >= len) {
        return;
    }
    // Append the first character of the first word
    buf.append(fullName.charAt(start));
    // Process remaining words
    for (int i = start + 1; i < len; i++) {
        char c = fullName.charAt(i);
        if (Character.isWhitespace(c)) {
            // Skip any additional whitespace
            while (i < len && Character.isWhitespace(fullName.charAt(i))) {
                i++;
            }
            if (i < len) {
                buf.append(fullName.charAt(i));
                i--; // counteract loop increment
            }
        }
    }
}

