    List<V> verts = new ArrayList<>(vertices);
    for (int i = 0; i < verts.size(); i++) {
        V u = verts.get(i);
        for (int j = i + 1; j < verts.size(); j++) {
            V v = verts.get(j);
            // For undirected graphs one getEdge() is enough.
            // For directed graphs we consider the subgraph complete if there is an edge
            // in either direction between every pair.
            if (graph.getEdge(u, v) == null && graph.getEdge(v, u) == null) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                if (!graph.containsEdge(v1, v2)) {
                    return false;
                }
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != null && v2 != null && !v1.equals(v2)) {
                if (graph.getEdge(v1, v2) == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

