private void pop(final String descriptor){
    int count = 0;
    if (descriptor == null || descriptor.length() == 0) return;
    try{
        if (descriptor.charAt(0) == '('){
            int i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')'){
                char c = descriptor.charAt(i);
                if (c == 'L'){
                    int semi = descriptor.indexOf(';', i);
                    if (semi == -1) throw new IllegalArgumentException("Malformed descriptor");
                    i = semi + 1;
                } else if (c == '['){
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') i++;
                    if (i >= descriptor.length()) throw new IllegalArgumentException("Malformed descriptor");
                    i++; // consume element type
                } else {
                    i++; // primitive type
                }
                count++;
            }
        } else {
            if (!descriptor.equals("V")) count = 1;
        }
        if (pos - count < 0) throw new IllegalStateException("Stack underflow");
        pos -= count;
    }catch(RuntimeException e){
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

private void pop(final String descriptor){
    if (descriptor == null){
        return;
    }
    String desc = descriptor;
    if (desc.startsWith("(")){
        int end = desc.indexOf(')');
        if (end < 0){
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        desc = desc.substring(1, end);
    }
    for (int i = 0; i < desc.length();){
        char c = desc.charAt(i++);
        switch (c){
            case '[':
                while (i < desc.length() && desc.charAt(i) == '['){
                    i++;
                }
                if (i < desc.length()){
                    if (desc.charAt(i) == 'L'){
                        while (i < desc.length() && desc.charAt(i) != ';'){
                            i++;
                        }
                        if (i < desc.length() && desc.charAt(i) == ';'){
                            i++;
                        }
                    } else {
                        // primitive array type (single char)
                        i++;
                    }
                }
                break;
            case 'L':
                while (i < desc.length() && desc.charAt(i) != ';'){
                    i++;
                }
                if (i < desc.length() && desc.charAt(i) == ';'){
                    i++;
                }
                break;
            default:
                // primitive type (single char)
                break;
        }
        // Pop one element from the stack
        pos--;
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int slotsToPop = 0;
    int idx = 0;

    // Handle method descriptor: "( ... )<return>"
    if (descriptor.charAt(0) == '(') {
        idx = 1;
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            char c = descriptor.charAt(idx);
            if (c == '[') { // array type
                // Skip all '[' characters
                while (idx < descriptor.length() && descriptor.charAt(idx) == '[') {
                    idx++;
                }
                // Skip component type
                if (idx < descriptor.length()) {
                    char comp = descriptor.charAt(idx);
                    if (comp == 'L') {
                        idx = descriptor.indexOf(';', idx) + 1; // skip object descriptor
                    } else {
                        idx++; // primitive component
                    }
                }
                slotsToPop++; // array occupies one slot
            } else if (c == 'L') { // object reference
                idx = descriptor.indexOf(';', idx) + 1;
                slotsToPop++;
            } else { // primitive type
                if (c == 'J' || c == 'D') {
                    slotsToPop += 2; // long and double take two slots
                } else if (c != 'V') { // 'V' should not appear in arguments, but skip if it does
                    slotsToPop++;
                }
                idx++;
            }
        }
    } else { // Standalone type descriptor
        while (idx < descriptor.length()) {
            char c = descriptor.charAt(idx);
            if (c == '[') { // array type
                while (idx < descriptor.length() && descriptor.charAt(idx) == '[') {
                    idx++;
                }
                if (idx < descriptor.length()) {
                    char comp = descriptor.charAt(idx);
                    if (comp == 'L') {
                        idx = descriptor.indexOf(';', idx) + 1;
                    } else {
                        idx++;
                    }
                }
                slotsToPop++;
            } else if (c == 'L') { // object reference
                idx = descriptor.indexOf(';', idx) + 1;
                slotsToPop++;
            } else { // primitive type
                if (c == 'J' || c == 'D') {
                    slotsToPop += 2;
                } else if (c != 'V') { // ignore void in standalone case
                    slotsToPop++;
                }
                idx++;
            }
        }
    }

    // Adjust the stack pointer (assuming a field named 'pos' is the stack top)
    pos -= slotsToPop;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    final int len = descriptor.length();
    if (len == 0) {
        return;
    }
    // handle simple type descriptor, e.g., "I", "Ljava/lang/String;"
    char c = descriptor.charAt(0);
    if (c == 'V') {
        // void type – nothing to pop
        return;
    }
    // For a method descriptor: e.g., "(ILjava/lang/String;)V"
    if (c == '(') {
        int i = 1; // start after '('
        while (i < len && descriptor.charAt(i) != ')') {
            // each loop iteration represents one argument type
            if (pos <= 0) {
                throw new IllegalStateException("stack underflow while popping arguments");
            }
            pos--; // pop one entry
            // skip this argument type
            char ch = descriptor.charAt(i);
            if (ch == '[') {
                do { i++; } while (descriptor.charAt(i) == '[');
                ch = descriptor.charAt(i);
            }
            if (ch == 'L') {
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
            } else {
                i++; // primitive
            }
        }
        // skip the ')'
        // return type is ignored for popping
        return;
    }

    // Non-method simple type: pop exactly one type
    if (pos <= 0) {
        throw new IllegalStateException("stack underflow while popping type");
    }
    pos--; // pop one entry

    // skip the single type descriptor (no need to set pos afterwards)
    // but we still advance index for completeness
    i = 0;
    char ch = descriptor.charAt(i);
    if (ch == '[') {
        while (descriptor.charAt(i) == '[') {
            i++;
        }
        ch = descriptor.charAt(i);
    }
    if (ch == 'L') {
        while (descriptor.charAt(i) != ';') {
            i++;
        }
    }
    // finished
}

private void pop(final String descriptor){
    int typeCount = 0;
    int i = 0;
    // Determine if descriptor is a method descriptor
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            // Handle array types
            while (c == '[') {
                i++;
                if (i >= descriptor.length()) break;
                c = descriptor.charAt(i);
            }
            // Handle object types
            if (c == 'L') {
                // consume until ';'
                i = descriptor.indexOf(';', i);
                if (i == -1) break; // malformed descriptor
            }
            // Now at a single primitive or the ';' of an object type
            i++;
            typeCount++;
        }
    } else {
        // Field descriptor: single type
        typeCount = 1;
    }
    // Pop the computed number of types from the output frame stack
    while (typeCount-- > 0 && pos > 0) {
        stack[--pos] = null;
    }
}

