    String[] baseParts = path.split("/");
    java.util.List<String> components = new java.util.ArrayList<>();
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            components.add(part);
        }
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip current directory or empty segments
            continue;
        } else if (part.equals("..")) {
            // Move one directory up if possible
            if (!components.isEmpty()) {
                components.remove(components.size() - 1);
            }
        } else {
            // Append normal path segment
            components.add(part);
        }
    }

    // Build the resulting path
    StringBuilder sb = new StringBuilder();
    // Preserve leading slash if original path started with it
    if (path.startsWith("/")) {
        sb.append("/");
    }
    for (int i = 0; i < components.size(); i++) {
        sb.append(components.get(i));
        if (i < components.size() - 1) {
            sb.append("/");
        }
    }
    return sb.length() == 0 ? "." : sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    if (relativePath.isEmpty() || relativePath.equals(".")) {
        return path;
    }
    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    java.util.List<String> result = new java.util.ArrayList<>();
    for (String p : pathParts) {
        if (p.isEmpty()) continue;
        result.add(p);
    }
    String[] relParts = relativePath.split("/");
    for (String r : relParts) {
        if (r.isEmpty() || r.equals(".")) {
            continue;
        } else if (r.equals("..")) {
            if (!result.isEmpty()) {
                result.remove(result.size() - 1);
            } else {
                if (!isAbsolute) result.add("..");
            }
        } else {
            result.add(r);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) sb.append("/");
    for (int i = 0; i < result.size(); i++) {
        if (i > 0) sb.append("/");
        sb.append(result.get(i));
    }
    if (sb.length() == 0) {
        return isAbsolute ? "/" : ".";
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // If the relativePath is actually absolute, just return it (normalized)
    if (relativePath.startsWith("/")) {
        String[] relParts = relativePath.split("/");
        java.util.List<String> parts = new java.util.ArrayList<>();
        for (String p : relParts) {
            if (p.isEmpty() || p.equals(".")) continue;
            if (p.equals("..")) {
                if (!parts.isEmpty()) {
                    parts.remove(parts.size() - 1);
                }
            } else {
                parts.add(p);
            }
        }
        return parts.isEmpty() ? "/" : String.join("/", parts).replaceAll("^", "/");
    }

    boolean leadingSlash = path.startsWith("/");
    String[] baseParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        stack.add(part);
    }

    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    if (stack.isEmpty()) {
        return leadingSlash ? "/" : "";
    }
    String result = String.join("/", stack);
    if (leadingSlash) {
        result = "/" + result;
    }
    return result;
}

