public boolean isExpired(long timestamp, long expiredThreshold){
    try {
        if (expiredThreshold < 0) {
            return false; // never expire
        }
        long current = System.currentTimeMillis();
        // avoid overflow by checking if timestamp is in the future
        long age = current - timestamp;
        if (age < 0) {
            return false; // timestamp hasn't passed yet
        }
        return age > expiredThreshold;
    } catch (Exception e) {
        // On any runtime error, conservatively do not expire
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // If threshold is not positive, assume never expires
        if (expiredThreshold <= 0) {
            return false;
        }
        long current = System.currentTimeMillis();
        return (current - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, log or handle accordingly
        // For safety, treat as not expired
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // If the threshold is non-positive, consider the entry never expirable
    if (expiredThreshold <= 0) {
        return false;
    }
    long currentTime = System.currentTimeMillis();
    // Avoid negative overflow when timestamp is in the future
    if (currentTime < timestamp) {
        return false;
    }
    return (currentTime - timestamp) > expiredThreshold;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    try{
        if (expiredThreshold <= 0) return false;
        long now = System.currentTimeMillis();
        return now - timestamp > expiredThreshold;
    }catch (Exception e){
        return false;
    }
}

public boolean isExpired(long timestamp,long expiredThreshold){
    // Treat non-positive thresholds as non-expires
    if (expiredThreshold <= 0) {
        return false;
    }
    // Expired when current time surpasses the threshold point
    return timestamp > expiredThreshold;
}

