int readTag() throws IOException {
    try {
        int result = 0;
        int shift = 0;
        while (true) {
            int b = read();
            if (b == -1) {
                return 0;
            }
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
            shift += 7;
            if (shift > 35) {
                throw new IOException("Malformed varint");
            }
        }
    } catch (EOFException e) {
        return 0;
    }
}

public int readTag() throws IOException {
    if (pos >= limit) {
        return 0;
    }
    int tag = 0;
    for (int shift = 0; shift < 32; shift += 7) {
        if (pos >= limit) {
            return 0;
        }
        int b = buf[pos++];
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
    }
    throw new IOException("Malformed varint");
}

